#include <iostream>
using namespace std;
int main() {
    // 1. Speed
    float d, t;
    cout << "Enter distance: "; cin >> d;
    cout << "Enter time: "; cin >> t;
    cout << "Speed = " << d/t << endl;
    // 2. Force
    float m, a;
    cout << "Enter mass: "; cin >> m;
    cout << "Enter acceleration: "; cin >> a;
    cout << "Force = " << m*a << endl;
    // 3. Acceleration
    float vf, vi;
    cout << "Enter final velocity: "; cin >> vf;
    cout << "Enter initial velocity: "; cin >> vi;
    cout << "Enter time: "; cin >> t;
    cout << "Acceleration = " << (vf-vi)/t << endl;
